func TestRunSuccess(t *testing.T) {
	fake := &fakeClient{}
	old := newClient
	newClient = func(cfg plugin.Config) jiraClient {
		if cfg.BaseURL != "https://jira.example.com" {
			t.Fatalf("unexpected base url: %s", cfg.BaseURL)
		}
		return fake
	}
	defer func() { newClient = old }()

	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_PLUGIN_BASE_URL":        "https://jira.example.com",
		"SEMREL_PLUGIN_EMAIL":           "bot@example.com",
		"SEMREL_PLUGIN_API_TOKEN":       "token",
		"SEMREL_PLUGIN_PROJECT_KEY":     "PROJ",
		"SEMREL_PLUGIN_TRANSITION_NAME": "Done",
		"SEMREL_VERSION":                "v1.2.3",
		"SEMREL_CHANGELOG":              "fix: PROJ-123\nfeat: PROJ-456",
	}), &stdout, &stderr)

	if code != 0 || stderr.String() != "plugin_schema_version=1\n" {
		t.Fatalf("unexpected result: code=%d stderr=%q", code, stderr.String())
	}
	if fake.createdProject != "PROJ" || fake.createdVersion != "v1.2.3" || fake.releasedID != "42" {
		t.Fatalf("unexpected client calls: %+v", fake)
	}
	if len(fake.transitions) != 2 {
		t.Fatalf("expected 2 transitions, got %v", fake.transitions)
	}
}

func TestRunDryRun(t *testing.T) {
	called := false
	old := newClient
	newClient = func(plugin.Config) jiraClient {
		called = true
		return &fakeClient{}
	}
	defer func() { newClient = old }()

	secretToken := "jira-secret-api-token-12345"
	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_PLUGIN_BASE_URL":        "https://jira.example.com",
		"SEMREL_PLUGIN_EMAIL":           "bot@example.com",
		"SEMREL_PLUGIN_API_TOKEN":       secretToken,
		"SEMREL_PLUGIN_PROJECT_KEY":     "PROJ",
		"SEMREL_PLUGIN_TRANSITION_NAME": "Done",
		"SEMREL_VERSION":                "v1.2.3",
		"SEMREL_CHANGELOG":              "fix: PROJ-123",
		"SEMREL_DRY_RUN":                "true",
	}), &stdout, &stderr)
	if code != 0 || called {
		t.Fatalf("unexpected result: code=%d called=%v", code, called)
	}
	if strings.Contains(stdout.String(), secretToken) || strings.Contains(stderr.String(), secretToken) {
		t.Fatalf("secret leaked in output: stdout=%q stderr=%q", stdout.String(), stderr.String())
	}
	if !strings.HasPrefix(stderr.String(), "plugin_schema_version=1\n") {
		t.Fatalf("missing schema version header: %q", stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-jira: would create and release version v1.2.3 in project PROJ at https://jira.example.com (token=***)") {
		t.Fatalf("unexpected stderr: %q", stderr.String())
	}
	var payload dryRunPayload
	if err := json.Unmarshal(stdout.Bytes(), &payload); err != nil {
		t.Fatalf("unmarshal dry-run payload: %v", err)
	}
	if payload.Destination != "https://jira.example.com" || payload.APIToken != "***" || payload.ProjectKey != "PROJ" || len(payload.IssueKeys) != 1 || payload.IssueKeys[0] != "PROJ-123" {
		t.Fatalf("unexpected dry-run payload: %+v", payload)
	}
}

func TestRunDryRunWithoutCredentials(t *testing.T) {
	var stdout, stderr bytes.Buffer
	code := run(context.Background(), env(map[string]string{
		"SEMREL_VERSION": "v1.2.3",
		"SEMREL_DRY_RUN": "true",
	}), &stdout, &stderr)
	if code != 0 {
		t.Fatalf("expected exit code 0 in dry-run without credentials, got %d (stderr=%q)", code, stderr.String())
	}
	if !strings.Contains(stderr.String(), "[dry-run] hook-jira: would need SEMREL_PLUGIN_BASE_URL, SEMREL_PLUGIN_EMAIL, SEMREL_PLUGIN_API_TOKEN, SEMREL_PLUGIN_PROJECT_KEY to release version in Jira") {
		t.Fatalf("expected missing credentials warning on stderr, got %q", stderr.String())
	}
	var payload dryRunPayload
	if err := json.Unmarshal(stdout.Bytes(), &payload); err != nil {
		t.Fatalf("unmarshal dry-run payload: %v", err)
	}
	if payload.Destination != "<unset>" || payload.APIToken != "<unset>" || payload.ProjectKey != "<unset>" {
		t.Fatalf("unexpected dry-run payload: %+v", payload)
	}
}

